    pnl = trades = 0
    long_, entry, bought = False, 0, 0
    for i, p in enumerate(prices):
        if not long_:
            if i >= 1 and p < prices[i - 1]:
                long_, entry, bought = True, p, i
        else:
            if (100 * p >= 105 * entry or 100 * p <= 97 * entry
                    or i - bought == 3):
                pnl += p - entry
                trades += 1
                long_ = False
    if long_:
        pnl += prices[-1] - entry
        trades += 1
    return [pnl, trades]

